contract InvMutTest {
    C c;
    uint T;
    uint w;

    constructor(C _c) { c = _c; }

    function run(uint totalWeightParam, uint voteWeightParam) public {
        require(totalWeightParam < 1e30);
        require(voteWeightParam < 1e30);
        T = totalWeightParam;
        w = voteWeightParam;
        c.init(address(this), address(this), address(this));
        c.newGrantProposal(address(this), 1);
        uint pid = c.proposalCount();
        uint votes = c.voteProposal(pid);
        bool majority = c.hasMajority(pid);
        bool quorum = c.hasQuorum(pid);
        bool minority = c.hasMinority(pid);
        assert(votes == w && (!majority || (quorum && minority)) && (!quorum || minority));
    }

    fallback(bytes calldata input) external returns (bytes memory) {
        bytes4 sel = bytes4(input[:4]);
        if (sel == iVAULT.totalWeight.selector) {
            return abi.encode(T);
        }
        return abi.encode(w);
    }

    receive() external payable {}
}

